#include <Preferences.h>
#include <Update.h>
#include <WiFi.h>
#include <esp_attr.h>
#include <esp_ota_ops.h>
#include <mbedtls/ecp.h>
#include <mbedtls/pk.h>
#include <mbedtls/sha256.h>

#include "ota_policy.h"
#include "settings.h"
